def transform(g):
 out=[r[:] for r in g]
 coords=[(i,j) for i,r in enumerate(g) for j,v in enumerate(r) if v==7]
 if coords:
  rmin=min(i for i,j in coords); rmax=max(i for i,j in coords); cmin=min(j for i,j in coords); cmax=max(j for i,j in coords)
  # line color 2 orientation
  pts=[(i,j) for i,r in enumerate(g) for j,v in enumerate(r) if v==2]
  if len({j for i,j in pts})==1:
   line=pts[0][1]; col=cmax+1 if cmin>line else cmin-1
   if 0<=col<len(g[0]):
    for i in range(len(g)): out[i][col]=8
  else:
   line=pts[0][0]; row=rmax+1 if rmax<line else rmin-1
   if 0<=row<len(g): out[row]=[8]*len(g[0])
 return out

